import * as THREE from 'three/webgpu';
import { texture, uv, uniform, vec3, mix, float, mul } from 'three/tsl';

export default function createNode(config, ctx) {
  const group = new THREE.Group();
  group.name = 'hub-pricing-card-1-plane';

  const width = 2.6;
  const height = 1.625;

  const geometry = new THREE.PlaneGeometry(width, height, 1, 1);
  const material = new THREE.MeshStandardNodeMaterial();

  const ink = new THREE.Color('#16161d');
  const paper = new THREE.Color('#e8ecf2');
  const accent = new THREE.Color('#ff2a38');
  const surface = new THREE.Color('#0b0b10');

  let map = null;
  try {
    map = ctx.textureLoader('/prism-assets/chrome/brushed-metal.map.png');
    if (map) {
      map.wrapS = THREE.RepeatWrapping;
      map.wrapT = THREE.RepeatWrapping;
      map.colorSpace = THREE.SRGBColorSpace;
    }
  } catch (e) {
    map = null;
  }

  const vUv = uv();

  // Engineered gradient: vertical mix from surface (near-black) to ink,
  // with a subtle accent sheen band and brushed-metal texture modulation.
  const gradientMix = mix(
    vec3(surface.r, surface.g, surface.b),
    vec3(ink.r, ink.g, ink.b),
    vUv.y
  );

  const sheenBand = float(0.06).mul(
    vUv.y.sub(0.5).abs().oneMinus().smoothstep(0.85, 1.0)
  );
  const accentSheen = mix(
    gradientMix,
    vec3(accent.r, accent.g, accent.b),
    sheenBand
  );

  let colorNode = accentSheen;

  if (map) {
    const texSample = texture(map, vUv);
    colorNode = mix(accentSheen, accentSheen.mul(texSample.rgb), float(0.35));
  }

  material.colorNode = colorNode;
  material.roughnessNode = float(0.55);
  material.metalnessNode = float(0.45);
  material.clearcoat = 0.18;
  material.clearcoatRoughness = 0.4;
  material.roughness = 0.55;
  material.metalness = 0.45;

  const mesh = new THREE.Mesh(geometry, material);
  mesh.name = 'hub-pricing-card-1-mesh';
  group.add(mesh);

  group.position.set(0, -0.3, 0);
  group.rotation.set(0, 0, 0);
  group.scale.set(1, 1, 1);

  group.userData.handlers = {};

  group.userData.cleanup = () => {
    geometry.dispose();
    material.dispose();
    if (map && map.dispose) {
      map.dispose();
    }
  };

  return group;
}
